import{_ as t,o as e,c as _,a3 as p}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/91-善用有效沟通，找寻合适伴侣.md","filePath":"books/attached/91-善用有效沟通，找寻合适伴侣.md","lastUpdated":1794316978000}'),o={name:"books/attached/91-善用有效沟通，找寻合适伴侣.md"};function r(s,a,n,d,c,i){return e(),_("div",null,[...a[0]||(a[0]=[p('<h3 id="善用有效沟通-找寻合适伴侣" tabindex="-1">善用有效沟通，找寻合适伴侣 <a class="header-anchor" href="#善用有效沟通-找寻合适伴侣" aria-label="Permalink to &quot;善用有效沟通，找寻合适伴侣&quot;">​</a></h3><p>跟伊桑（Ethan）约会了几次后，劳伦（Lauren）就陷入了困惑。第一次约会，他们挑了一家浪漫的沙滩酒吧，花了好几个小时来了解对方。可是晚上告别时，伊桑草草说了再见就消失了。可是劳伦很惊讶的是，下一次伊桑还是约她出去了，这次是在一家海滨俱乐部，两人喝了几杯酒，还一起跳舞。他们甚至还在沙滩上漫步了一会，但还是什么都没有发生。在道别时，伊桑只是说了一句“再联系”。几次约会过后，这种情形一再发生。劳伦是个焦虑型依恋风格的人，她简单地认为伊桑就是对她不那么动心。可是他又为什么一直在主动邀约呢？他是不是只想要个人陪他？她不想再用恶意揣测他，因为真的对他印象很不错。一位闺蜜鼓励她，别再对伊桑的行为不停地揣测，直截了当问他就好。</p><p>而劳伦自然是没有这个勇气的，她太害怕自己得到什么回应，从而受到伤害。但是，她清楚地意识到，自己不能再将宝贵的时间浪费在错的人身上。她向伊桑提出了这个问题，一开始只是试探的口气，后来却发现自己在谈话时说得非常直接：“我可不想谈一场柏拉图恋爱，你是怎么想的呢？”而出乎她的所料，伊桑完全没有觉得劳伦缺乏吸引力。他表示自己非常喜欢劳伦，也很想找一个伴儿。但是当劳伦问及他的长远打算，特别强调他“避免肢体接触”的问题时，他却没有明确给出答案，不停地顾左右而言他。因此，即使她最终没有得知他为何抗拒身体接触，却清晰地预见到了他们的未来——两人绝无可能！</p><p>至此，劳伦打消了将伊桑作为潜在伴侣的念头，两人还是继续做朋友。后来，伊桑也向她坦白，自己约会的好几个女孩都因为他迷雾重重的行为而感到挫败，而劳伦最后终于做出了正确的判断。伊桑的神秘行为其实一目了然——他显然是对自己的性取向有着严重的怀疑。劳伦非常庆幸自己鼓起了勇气，向伊桑袒露了自己的顾虑，避免了自己痴痴等待几个月，最后还是失望而归。</p><p>劳伦的故事就是有效沟通的一个良好例证，直截了当地向伴侣表达自己的需求与期望，无疑是一种很不错的方式。虽然对于安全型依恋风格的人来说，这种方式是很平常的，可对于焦虑型或回避型的人来说，采取这种方式却是有些违反天性的。</p><p>与伊桑的一次开诚布公的谈话，非常有效地结束了劳伦心中一切的无端猜测与“说辞”。而对于伊桑来说，劳伦愿意将他的行为摆上台面来说，并且表示理解，也算是一种解脱。他其实只是想找个女朋友带回家，跟亲朋好友交代，来避免他们催促自己找对象，他也同样需要一些时间，来厘清自己的性取向问题。而通过表达自己的需求，劳伦也可以将自己的情绪照顾到，不必被他人牵着鼻子走。在劳伦的例子中，依恋风格并不是关键问题，但若是不说开了，事先也不会知道到底是什么状况。如果伊桑的一系列行为仅仅是依恋风格使然，有效沟通也可以将事实揭示出来。起码在冲突不可调和之前，充分了解对方的依恋风格问题，这对于双方来讲，都没什么坏处。</p><p>那么会不会有这种可能，劳伦以这种直接的方式与伊桑对峙，令对方窘迫不堪，最后发现这些行为既非源于依恋风格，也无关乎性取向，而仅仅是因为他很害羞呢？没错，我们真的遇到过有这种经历的人。</p><p>蒂娜（Tina）的境遇与劳伦非常相似，在她与赛格（Serge）的三次约会中，蒂娜就在沙发上与其并排坐着看电影，期待着赛格有进一步动作。她和劳伦一样，担心自己的感情无疾而终，也不想浪费过多的时间去猜测赛格这样做到底有什么隐情。于是，她带着风情万种的微笑，直截了当地说：“你可以吻我一下吗？”赛格愣了一秒，一时说不出话来，不过他马上就恢复了神志，俯下身子来吻了她。而从那以后，他再没有在交往中扭扭捏捏，他们在一起都三年了，感情依然很好。</p><p>在这个案例中，富有情调的索吻，显然是一种强有力的有效沟通方式。虽然蒂娜提出要求的那一刻还是有点煎熬，但她的直接，的确为两个人的关系进展助力不少，令两人的亲密更进一步了，不论在身体上还是情感上，都是如此。即使当时赛格呈现出另一种反应，致使事情走向另一种结局，而这种有效的沟通依然是有益的。毕竟人们对于有效的沟通，往往都会产生比较显著的回应。无论是像劳伦和伊桑一样，揭示出两个人的不可能；还是像蒂娜与赛格一样，令两人关系迅速升温。</p><p>有效沟通的实现有一个前提，就是我们要知道在亲密关系中，不同依恋风格的人会有不同的需求。这些需求各有差别，但是不分好坏。作为焦虑型依恋风格，你会产生很强烈的亲密需求，无时无刻都需要确认伴侣对你的爱与尊重。而回避型的人则更看重保持距离，无论在身体还是情感上，都希望和伴侣之间留有一定空间。为了亲密关系的和谐，我们应该摒弃攻击与防御行为，找到有效的方式来清楚地沟通彼此的亲密需求。</p>',10)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
